import "../std/natx.ouro";
def expansion_power (base : Nat) (exponent : Nat) : Nat := pow_nat base exponent;
def expansion_success (E : Type) (A : Type) (value : A) : Either E A := Right E A value;
def expansion_shifted_power (base : Nat) (exponent : Nat) : Nat := pow_nat base (S exponent);

support.imported_contract_support/wrappers.ouro:
import "../std/natx.ouro";
import "../std/io.ouro";
import "../std/string_prims.ouro";
import "../expansion_support/delegates.ouro";
def chained_power (base : Nat) (exponent : Nat) : Nat := expansion_power base exponent;
def reversed_divisor (n : Nat) (d : Nat) : Nat := div_nat d n;
def duplicated_divisor (n : Nat) (d : Nat) : Nat := div_nat n n;
def shadowed_power (pow_nat : Nat -> Nat -> Nat) (base : Nat) (exponent : Nat) : Nat := pow_nat base exponent;
def annotated_power (base : Nat) (exponent : Nat) : Nat := let same : Nat := exponent in pow_nat base same;
def preceding_action (action : IO Unit) (base : Nat) (exponent : Nat) : IO Nat := (do action; io_pure Nat (pow_nat base exponent));
